operation.add:
/** avalon кредитен калкулатор **/
$data['is_active_jet'] = true;
$data['jet_product_css'] = '';
$data['jet_product_js'] = '';
$jet_status = $this->config->get('module_mt_jet_credit_status');
if ($jet_status) {
    if (isset($this->request->get['product_id'])) {
        $data['jet_product_id'] = (int)$this->request->get['product_id'];
    } else {
        $data['jet_product_id'] = 0;
    }
    $config_customer_price = $this->config->get('config_customer_price');
    if (($config_customer_price && $this->customer->isLogged()) || !$config_customer_price) {
        if ((float)$product_info['special']){
            $jet_price = $this->tax->calculate($product_info['special'], $product_info['tax_class_id'], $this->config->get('config_tax'));
        }else{
            $jet_price = $this->tax->calculate($product_info['price'], $product_info['tax_class_id'], $this->config->get('config_tax'));
        }
    } else {
        $jet_price = 0;
    }
    $data['jet_price'] = (float)$jet_price;

    $jet_currency_code = $this->session->data['currency'];
    // Проверка дали продуктът е в наличност
    $product_in_stock = $product_info['quantity'] > 0;

    if ($product_in_stock && ($jet_currency_code == 'EUR' || $jet_currency_code == 'BGN')) {
        $data['jet_eur'] = (int) $this->config->get('module_mt_jet_credit_eur');
        $data['jet_sign'] = 'лв.';
        $data['jet_sign_second'] = 'евро';
        $jet_min_250 = 250.00;
        switch ($data['jet_eur']) {
            case 0:
                $data['jet_sign'] = 'лв.';
                $data['jet_sign_second'] = '';
                break;
            case 1:
                if ($jet_currency_code == "EUR") {
                    $jet_price = number_format($jet_price * 1.95583, 2, ".", "");
                }
                $data['jet_sign'] = 'лв.';
                $data['jet_sign_second'] = 'евро';
                break;
            case 2:
                if ($jet_currency_code == "BGN") {
                    $jet_price = number_format($jet_price / 1.95583, 2, ".", "");
                }
                $data['jet_sign'] = 'евро';
                $data['jet_sign_second'] = 'лв.';
                $jet_min_250 = 125.00;
                break;
            case 3:
                if ($jet_currency_code == "BGN") {
                    $jet_price = number_format($jet_price / 1.95583, 2, ".", "");
                }
                $data['jet_sign'] = 'евро';
                $data['jet_sign_second'] = '';
                $jet_min_250 = 125.00;
                break;
        }

        if ($jet_price < $jet_min_250) {
            $data['jet_vnoski'] = '9';
        }else{
            $data['jet_vnoski'] = $this->config->get('module_mt_jet_credit_vnoski');
        }
        $data['jet_card_in'] = (int)$this->config->get('module_mt_jet_credit_status_card');
        $data['jet_gap'] = (int)$this->config->get('module_mt_jet_credit_gap');
        $data['jet_button_type'] = $this->config->get('module_mt_jet_credit_button_type') ? $this->config->get('module_mt_jet_credit_button_type') : 'standard';
        $this->load->model('extension/mt_jet_credit/jetcredit');
        $data['jet_button_scheme_style'] = $this->model_extension_mt_jet_credit_jetcredit->getJetWideButtonInlineStyle($this->config->get('module_mt_jet_credit_button_scheme'));
        $_jbtn = $this->config->get('module_mt_jet_credit_btn_text');
        $data['jet_btn_text'] = ($_jbtn === null || $_jbtn === '') ? 'Купи на изплащане с' : $_jbtn;
        $_jbtnc = $this->config->get('module_mt_jet_credit_btn_text_card');
        $data['jet_btn_text_card'] = ($_jbtnc === null || $_jbtnc === '') ? 'На вноски с твоята кредитна карта' : $_jbtnc;
        $_jblg = $this->config->get('module_mt_jet_credit_btn_logo');
        $data['jet_btn_logo'] = $_jblg === null || $_jblg === '' ? 1 : ((int) $_jblg ? 1 : 0);
        $_jbmw = $this->config->get('module_mt_jet_credit_btn_max_width');
        $data['jet_button_scheme_style'] .= '--jet-wide-max-width:' . (($_jbmw === null || $_jbmw === '') ? 570 : min(1200, max(30, (int) $_jbmw))) . 'px;';
        $_jbrnd = $this->config->get('module_mt_jet_credit_btn_round');
        $data['jet_button_scheme_style'] .= '--jet-wide-radius:' . (($_jbrnd === null || $_jbrnd === '') ? 16 : min(25, max(0, (int) $_jbrnd))) . 'px;';
        $_jbfnt = $this->config->get('module_mt_jet_credit_btn_font');
        $data['jet_button_scheme_style'] .= '--jet-wide-font-size:' . (($_jbfnt === null || $_jbfnt === '') ? 14 : min(36, max(6, (int) $_jbfnt))) . 'px;';
        $data['jet_vnoska'] = (int)$this->config->get('module_mt_jet_credit_vnoska');
        $data['image_jet'] = 'catalog/view/theme/default/image/jet.png';
        $data['image_jet_card'] = 'catalog/view/theme/default/image/jet_card.png';
        $jet_assets_base = DIR_APPLICATION . 'view/theme/default/template/extension/mt_jet_credit/';
        $data['jet_product_css'] = 'catalog/view/theme/default/template/extension/mt_jet_credit/creditjet_products.css?ver=' . filemtime($jet_assets_base . 'creditjet_products.css');
        $data['jet_product_js'] = 'catalog/view/theme/default/template/extension/mt_jet_credit/creditjet_products.js?ver=' . filemtime($jet_assets_base . 'creditjet_products.js');

        $this->load->model('account/customer');
        $data['jet_name'] = "";
        $data['jet_lastname'] = "";
        $data['jet_email'] = "";
        $data['jet_phone'] = "";
        if ($this->customer->isLogged()) {
            $customer_id = $this->customer->getId();
            $customer_info = $this->model_account_customer->getCustomer($customer_id);
            $data['jet_name'] = $customer_info['firstname'];
            $data['jet_lastname'] = $customer_info['lastname'];
            $data['jet_email'] = $this->customer->getEmail();
            $data['jet_phone'] = $customer_info['telephone'];
        }

    }else{
        $data['is_active_jet'] = false;
    }
}else{
    $data['is_active_jet'] = false;
}
