$this->document->addScript('catalog/view/theme/default/template/extension/mt_jet_credit/creditjet_cart.js?ver='.filemtime(DIR_APPLICATION . "view/theme/default/template/extension/mt_jet_credit/creditjet_cart.js"));
$this->document->addStyle('catalog/view/theme/default/template/extension/mt_jet_credit/creditjet_cart.css?ver='.filemtime(DIR_APPLICATION . "view/theme/default/template/extension/mt_jet_credit/creditjet_cart.css"));
