    $products_jet['option'][$products_jet_index][$key]['product_option_value_id'] = $value['product_option_value_id'];
    $products_jet['option'][$products_jet_index][$key]['option_id'] = $value['option_id'];
    $products_jet['option'][$products_jet_index][$key]['option_value_id'] = $value['option_value_id'];
    $products_jet['option'][$products_jet_index][$key]['name'] = $value['name'];
    $products_jet['option'][$products_jet_index][$key]['value'] = $value['value'];
    $products_jet['option'][$products_jet_index][$key]['type'] = $value['type'];
}
$products_jet_index++;
