$data['is_active_jet'] = true;
$jet_status = $this->config->get('module_mt_jet_credit_status');
$jet_card_show = $this->config->get('module_mt_jet_credit_cart_show');
if ($jet_status && $jet_card_show) {
    $data['jet_products'] = substr($products_jet['id'], 0, -1);
    $data['jet_products_pr'] = substr($products_jet['pr'], 0, -1);
    $data['jet_products_qt'] = substr($products_jet['quantity'], 0, -1);
    $data['jet_products_vr'] = json_encode($products_jet['option']);
    $jet_price = $products_jet['price'];
    $data['jet_price'] = $jet_price;

    $jet_currency_code = $this->session->data['currency'];
    if ($jet_currency_code == 'EUR' || $jet_currency_code == 'BGN') {
        $data['jet_eur'] = (int) $this->config->get('module_mt_jet_credit_eur');
        $data['jet_sign'] = 'лв.';
        $data['jet_sign_second'] = 'евро';
        $jet_min_250 = 250.00;
        switch ($data['jet_eur']) {
            case 0:
                $data['jet_sign'] = 'лв.';
                $data['jet_sign_second'] = '';
                break;
            case 1:
                if ($jet_currency_code == "EUR") {
                    $jet_price = number_format($jet_price * 1.95583, 2, ".", "");
                }
                $data['jet_sign'] = 'лв.';
                $data['jet_sign_second'] = 'евро';
                break;
            case 2:
                if ($jet_currency_code == "BGN") {
                    $jet_price = number_format($jet_price / 1.95583, 2, ".", "");
                }
                $data['jet_sign'] = 'евро';
                $data['jet_sign_second'] = 'лв.';
                $jet_min_250 = 125.00;
                break;
            case 3:
                if ($jet_currency_code == "BGN") {
                    $jet_price = number_format($jet_price / 1.95583, 2, ".", "");
                }
                $data['jet_sign'] = 'евро';
                $data['jet_sign_second'] = '';
                $jet_min_250 = 125.00;
                break;
        }

        $_minprice = $this->config->get('module_mt_jet_credit_price');
        if ($jet_price >= $_minprice) {
            if ($jet_price < $jet_min_250) {
                $data['jet_vnoski'] = '9';
            }else{
                $data['jet_vnoski'] = $this->config->get('module_mt_jet_credit_vnoski');
            }
            $data['jet_card_in'] = (int)$this->config->get('module_mt_jet_credit_status_card');
            $data['jet_gap'] = (int)$this->config->get('module_mt_jet_credit_gap');
